mapper.select:
 select mn.*,pre.p_name as projectName
 from Settlement_Audit mn
left join pre_project pre on pre.p_id = mn.project_id
 
     mn.status=1 and mn.del_flag=1
     
         and pre.p_name in
         
             #{pName}
         
     
     
         and mn.state in
         
             #{state}
         
     
     
         and mn.audit_Contract_Num in
         
             #{auditContractNum}
         
     
     
         and mn.audit_Contract_Money in
         
             #{auditContractMoney}
         
     
     
         and mn.create_Uname in
         
             #{createUname}
         
     
 
 order by mn.Create_Time desc
